const q = $input.first().json.query || {};
// Estado del cobro real. Si n8n bloquea el acceso a $env no se puede saber si
// MercadoPago está activo, y adivinar sería abrir de nuevo S2: se falla cerrado.
let mpConfigurado;
try {
  mpConfigurado = (typeof $env !== 'undefined' && $env) ? Boolean($env.MP_ACCESS_TOKEN) : false;
} catch (e) {
  throw new Error('No se puede leer MP_ACCESS_TOKEN: n8n tiene bloqueado el acceso al entorno en los nodos Code. Configurar N8N_BLOCK_ENV_ACCESS_IN_NODE=false (ver docker-compose.yml) para habilitar el modo de desarrollo.');
}
if (mpConfigurado) throw new Error('Modo de desarrollo deshabilitado: hay credenciales de MercadoPago configuradas');
if (!q.factura_id) throw new Error('Falta factura_id');
// pago_token (S1 de la Tabla 11, cerrada): sin él, factura_id solo (10.000
// combinaciones adivinables por año) alcanzaba para marcar cualquier
// factura como cobrada. Se verifica contra la base en el próximo nodo.
if (!q.pago_token) throw new Error('Falta pago_token');
return [{ json: { factura_id: q.factura_id, pago_token: q.pago_token, lead_id: q.lead_id || '' } }];

const l = $('Code - Generar Propuesta').first().json;
const leerEnv = (clave, porDefecto) => {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined;
    return (v === undefined || v === null || v === '') ? porDefecto : String(v);
  } catch (e) { return porDefecto; }
};
// Base de Notion con las cards de leads. Requiere N8N_BLOCK_ENV_ACCESS_IN_NODE=false.
const DATABASE_ID = leerEnv('NOTION_DATABASE_ID', 'REEMPLAZAR_DATABASE_ID');
const body = {
  parent: { database_id: DATABASE_ID },
  properties: {
    Name: { title: [{ text: { content: String(l.nombre || 'Lead') } }] },
    Estado: { select: { name: 'PROPUESTA_ENVIADA' } },
    Tier: { select: { name: String(l.tier || 'COLD') } },
    Servicio: { select: { name: String(l.servicio || 'otro') } },
    Email: { email: String(l.email || 'sin@email.com') },
    Presupuesto: { number: Number(l.presupuesto) || 0 },
    Score: { number: Number(l.score) || 0 },
    'Lead ID': { rich_text: [{ text: { content: String(l.lead_id || '') } }] }
  }
};
return [{ json: { lead_id: l.lead_id, notion_body: body } }];

const item = $input.first().json.body || {};
const capitalizar = (s) => s.replace(/\S+/gu, (w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());
const nombre = capitalizar((item.nombre || '').trim().replace(/\s+/g, ' '));
const email = (item.email || '').toLowerCase().trim();
const presupuesto = parseInt(item.presupuesto) || 0;
const urg = ['alta', 'media', 'baja'];
const urgencia = urg.includes((item.urgencia || '').toLowerCase()) ? item.urgencia.toLowerCase() : 'media';
const svcMap = { 'desarrollo web':'desarrollo_web','e-commerce':'ecommerce','ecommerce':'ecommerce','app móvil':'app_movil','app movil':'app_movil','app_movil':'app_movil','diseño ux/ui':'diseno_ui','diseno ux/ui':'diseno_ui','marketing digital':'marketing','seo / posicionamiento':'seo','seo/posicionamiento':'seo','automatización de procesos':'automatizacion','automatizacion de procesos':'automatizacion','automatizacion':'automatizacion','consultoría':'consultoria','consultoria':'consultoria','otro':'consultoria','soporte':'soporte','desarrollo_web':'desarrollo_web','diseno_ui':'diseno_ui','marketing':'marketing','seo':'seo' };
const servicio = svcMap[(item.servicio || '').toLowerCase().trim()] || 'consultoria';
const errores = [];
if (!email.includes('@')) errores.push('email invalido');
if (nombre.length < 2) errores.push('nombre muy corto');
if (presupuesto <= 0) errores.push('presupuesto invalido');
if (errores.length) throw new Error('Validacion fallida: ' + errores.join(', '));
const ts = Date.now();
const rand = Math.random().toString(36).substring(2, 6).toUpperCase();
return [{ json: { lead_id: 'LD-' + ts + '-' + rand, nombre, email, presupuesto, urgencia, servicio, telefono: (item.telefono || '').trim(), descripcion: (item.descripcion || '').trim().substring(0, 2000), fuente: item.fuente || 'webhook' } }];

// Calificación del lead. Los pesos y los umbrales de tier NO son constantes
// de código: salen de variables de entorno, de modo que el criterio de
// calificación se puede recalibrar sin tocar el workflow (§6, cuestión 3 del
// dictamen). Los defaults reproducen exactamente la Tabla 4 de la tesis.
const leerEnv = (clave, porDefecto) => {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined;
    return (v === undefined || v === null || v === '') ? porDefecto : String(v);
  } catch (e) { return porDefecto; }
};
// "umbral:puntos,umbral:puntos" evaluado de mayor a menor.
const tramos = (clave, porDefecto) => leerEnv(clave, porDefecto)
  .split(',')
  .map((p) => p.split(':'))
  .map(([k, v]) => [Number(k), Number(v)])
  .filter(([k, v]) => Number.isFinite(k) && Number.isFinite(v))
  .sort((a, b) => b[0] - a[0]);
// "clave:puntos,clave:puntos"
const tabla = (clave, porDefecto) => Object.fromEntries(
  leerEnv(clave, porDefecto)
    .split(',')
    .map((p) => p.split(':'))
    .filter((p) => p.length === 2)
    .map(([k, v]) => [String(k).trim(), Number(v)])
);

const l = $input.first().json;
let score = 0;

const presupuesto = parseInt(l.presupuesto) || 0;
for (const [minimo, puntos] of tramos('SCORING_PRESUPUESTO', '5000:40,2000:30,1000:20,300:10')) {
  if (presupuesto >= minimo) { score += puntos; break; }
}

const porUrgencia = tabla('SCORING_URGENCIA', 'alta:30,media:15,baja:5');
score += porUrgencia[l.urgencia] !== undefined ? porUrgencia[l.urgencia] : Number(leerEnv('SCORING_URGENCIA_DEFAULT', '5'));

const porServicio = tabla('SCORING_SERVICIO', 'desarrollo_web:20,ecommerce:20,app_movil:18,automatizacion:18,marketing:15,seo:15,diseno_ui:15,consultoria:12,soporte:5');
score += porServicio[l.servicio] !== undefined ? porServicio[l.servicio] : Number(leerEnv('SCORING_SERVICIO_DEFAULT', '8'));

if (l.telefono && l.telefono.length > 6) score += Number(leerEnv('SCORING_BONUS_TELEFONO', '5'));
if (l.descripcion && l.descripcion.length > 50) score += Number(leerEnv('SCORING_BONUS_DESCRIPCION', '5'));

const umbralHot = Number(leerEnv('SCORING_UMBRAL_HOT', '70'));
const umbralWarm = Number(leerEnv('SCORING_UMBRAL_WARM', '40'));
const tier = score >= umbralHot ? 'HOT' : score >= umbralWarm ? 'WARM' : 'COLD';

return [{ json: Object.assign({}, l, { score: score, tier: tier }) }];

const l = $input.first().json;
const primerNombre = String(l.nombre || 'Cliente').split(' ')[0];
const svc = String(l.servicio || 'servicio').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
// El plazo, el precio y el alcance los fija el profesional al enviar la
// propuesta. El respaldo por urgencia queda sólo para las propuestas
// anteriores a que esa función existiera.
const tiempo = String(l.plazo_propuesto || '').trim() || ((l.urgencia === 'alta') ? '3-5 dias habiles' : '1-2 semanas');
const precio = Number(l.precio_propuesto) > 0 ? Number(l.precio_propuesto) : Number(l.presupuesto) || 0;
const alcance = String(l.alcance_propuesto || '').trim().replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/\n/g, '<br>');
const leerEnv = (clave, porDefecto) => {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined;
    return (v === undefined || v === null || v === '') ? porDefecto : String(v);
  } catch (e) { return porDefecto; }
};
// URL pública del front. Se configura con FRONTEND_URL (ver .env.example).
const FRONT_BASE = leerEnv('FRONTEND_URL', 'http://localhost:3000').replace(/\/+$/, '');
const acceptUrl = FRONT_BASE + '/aceptar/' + encodeURIComponent(l.lead_id) + '?token=' + encodeURIComponent(l.accept_token);
const html = `<!DOCTYPE html><html><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'></head><body style='margin:0;background:#f4f4f5;font-family:Arial,Helvetica,sans-serif;color:#27272a'><div style='max-width:600px;margin:0 auto;background:#ffffff'><div style='background:#111827;padding:32px 40px'><div style='color:#fbbf24;font-size:20px;font-weight:800;letter-spacing:1px'>SODEROS S.A.</div><div style='color:#9ca3af;font-size:12px;letter-spacing:2px;text-transform:uppercase;margin-top:4px'>Propuesta de trabajo</div></div><div style='padding:40px'><p style='font-size:16px;margin:0 0 8px'>Hola <b>${primerNombre}</b>,</p><p style='font-size:15px;line-height:1.6;color:#52525b;margin:0 0 28px'>Gracias por tu interes. Preparamos una propuesta para tu proyecto de <b>${svc}</b>:</p><table style='width:100%;border-collapse:collapse;margin:0 0 28px'><tr><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;color:#71717a;font-size:13px'>Servicio</td><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;text-align:right;font-weight:700'>${svc}</td></tr>${alcance ? "<tr><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;color:#71717a;font-size:13px;vertical-align:top'>Alcance</td><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;text-align:right;line-height:1.5'>" + alcance + '</td></tr>' : ''}<tr><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;color:#71717a;font-size:13px'>Tiempo de entrega</td><td style='padding:14px 0;border-bottom:1px solid #e4e4e7;text-align:right;font-weight:700'>${tiempo}</td></tr><tr><td style='padding:14px 0;color:#71717a;font-size:13px'>Inversion</td><td style='padding:14px 0;text-align:right;font-weight:800;font-size:18px;color:#111827'>${precio} USD</td></tr></table><div style='text-align:center;margin:0 0 24px'><a href='${acceptUrl}' style='display:inline-block;background:#fbbf24;color:#111827;padding:16px 40px;border-radius:8px;text-decoration:none;font-weight:800;font-size:15px'>Ver propuesta y responder</a></div><p style='font-size:13px;line-height:1.6;color:#a1a1aa;text-align:center;margin:0'>Desde el enlace vas a poder <b>aceptar</b>, <b>pedir cambios</b> o <b>rechazar</b> la propuesta.</p></div><div style='background:#fafafa;padding:24px 40px;border-top:1px solid #e4e4e7'><p style='margin:0;font-size:13px;color:#71717a'>Saludos,<br><b style='color:#27272a'>Equipo Soderos S.A.</b></p></div></div></body></html>`;
return [{ json: Object.assign({}, l, { propuesta_html: html, accept_url: acceptUrl }) }];

