const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const l = items[i].json;
  const numSeg = (parseInt(l.seguimientos) || 0) + 1;
  const nombre = String(l.nombre || 'Cliente').split(' ')[0];
  const servicio = String(l.servicio || 'proyecto').replace(/_/g, ' ');
  // El seguimiento invita a revisar la propuesta, así que tiene que llevarla:
  // sin enlace el cliente debe rescatar un correo de días atrás.
  const leerEnv = (clave, porDefecto) => {
    try {
      const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined;
      return (v === undefined || v === null || v === '') ? porDefecto : String(v);
    } catch (e) { return porDefecto; }
  };
  const FRONT = leerEnv('FRONTEND_URL', 'http://localhost:3000').replace(/\/+$/, '');
  const verUrl = FRONT + '/aceptar/' + encodeURIComponent(l.lead_id) + '?token=' + encodeURIComponent(l.accept_token);
  const textos = {
    1: 'Quería saber si pudiste ver la propuesta de ' + servicio + '. Quedo a disposición por cualquier duda.',
    2: 'La propuesta de ' + servicio + ' sigue vigente. ¿Hay algo que quieras ajustar o revisar?',
    3: 'Último contacto por el proyecto de ' + servicio + '. Si más adelante decidís retomarlo, con gusto lo hablamos. ¡Saludos!'
  };
  const cuerpo = textos[numSeg] || textos[3];
  const esUltimo = numSeg >= 3;
  const html = `<!DOCTYPE html><html><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'></head><body style='margin:0;background:#f4f4f5;font-family:Arial,Helvetica,sans-serif;color:#27272a'><div style='max-width:600px;margin:0 auto;background:#ffffff'><div style='background:#111827;padding:28px 40px'><div style='color:#fbbf24;font-size:20px;font-weight:800;letter-spacing:1px'>SODEROS S.A.</div><div style='color:#9ca3af;font-size:12px;letter-spacing:2px;text-transform:uppercase;margin-top:4px'>Seguimiento</div></div><div style='padding:40px'><p style='font-size:16px;margin:0 0 8px'>Hola <b>${nombre}</b>,</p><p style='font-size:15px;line-height:1.6;color:#52525b;margin:0'>${cuerpo}</p><div style='text-align:center;margin:28px 0 0'><a href='${verUrl}' style='display:inline-block;background:#fbbf24;color:#111827;padding:14px 34px;border-radius:8px;text-decoration:none;font-weight:800;font-size:15px'>Ver la propuesta</a></div></div><div style='background:#fafafa;padding:22px 40px;border-top:1px solid #e4e4e7'><p style='margin:0;font-size:13px;color:#71717a'>Saludos,<br><b style='color:#27272a'>Equipo Soderos S.A.</b></p></div></div></body></html>`;
  out.push({ json: Object.assign({}, l, { num_seg: numSeg, email_subject: 'Seguimiento: Propuesta ' + servicio, email_body: html, es_ultimo: esUltimo }), pairedItem: { item: i } });
}
return out;

