  factura_id: fid,
  pago_token: pagoToken,
  monto: monto,
  moneda: moneda,
  comision_plataforma: comision,
  fecha_emision_iso: new Date().toISOString(),
  fecha_vencimiento_iso: new Date(Date.now() + dias * 86400000).toISOString(),
  mp_preference_body: preferencia
} }];

// Idéntico criterio que `Code - Resolver Link de Pago` de la rama de aceptación:
// con MercadoPago configurado el enlace es el checkout real; sin credenciales
// (o si MP no respondió) cae al enlace del modo de desarrollo. Así la factura
// reconciliada no es una factura de segunda: entra al circuito de recordatorios
// con el mismo enlace de pago que habría tenido de haberse emitido a tiempo.
const l = $('Code - Preparar Factura Reconciliada').first().json;
const r = $input.first().json || {};
const leerEnv = (clave, porDefecto) => {
  try {
    const v = (typeof $env !== 'undefined' && $env) ? $env[clave] : undefined;
    return (v === undefined || v === null || v === '') ? porDefecto : String(v);
  } catch (e) { return porDefecto; }
};
const BASE = leerEnv('N8N_PUBLIC_URL', 'http://localhost:5678/').replace(/\/+$/, '');
const linkDesarrollo = BASE + '/webhook/pago-confirmado?factura_id=' + l.factura_id + '&pago_token=' + l.pago_token + '&lead_id=' + l.lead_id;
const initPoint = r.init_point || r.sandbox_init_point || '';
return [{ json: Object.assign({}, l, {
  payUrl: initPoint || linkDesarrollo,
  mp_preference_id: r.id ? String(r.id) : null
}) }];

